    troll.Position = C3DVector(4.0f, 6.0f, 1.0f);
    troll.OldPosition = C3DVector(1.0f, 2.0f, 1.0f);
    troll.HelperPoint = C3DVector(9.0f, 8.0f, 7.0f);
    Log log;
    Action action = { &troll, "TROLL_WHACK", true, &log };

