        if (UpdateFlags & 2) Log("UPSC;");
        if ((flags & 0x400) && (UpdateFlags & 0x20)) Log("BONE;");
        if (UpdateFlags & 4) Log("AMB;");
        if (UpdateFlags & 0x20000) Log("FOG;");
